INSERT INTO `achievement_reward_locale` (`ID`, `Locale`, `Subject`, `Body`) VALUES
(13, 'ruRU', '80-й уровень', 'Поздравляю с твоей решимостью достичь 80-го этапа приключений. Ты несомненно предан делу избавления Азерота от зла, которое нас преследует.$B$BИ хотя пройденный путь был совсем не лёгким испытанием, настоящая битва ещё впереди.$B$BСражайся дальше!$B$BРонин'),
(2137, 'ruRU', 'Слава рейдера (10 игроков)', 'Чемпион, $B$BВесть дошла до Вирмрестского храма о твоих великих деяниях, совершённых с момента прибытия в Нордскол. $B$BТвоя доблесть не должна остаться незамеченной. Прими этот дар от имени Аспектов. Вместе мы избавим Азерот от зла, теперь и навечно. $B$BАлекстраза Жизнедательница.'),
(2138, 'ruRU', 'Слава рейдера (25 игроков)', NULL),
(2516, 'ruRU', 'Друг, о котором стоит позаботиться', 'Привет!$B$BЯ слышала, что ты сумел найти тёплый и любящий дом даже для этого проказника Вонючки... Я надеялась, что ты рассмотришь возможность взять ещё одного бедного сиротку?$B$BЭтот маленький олененок немного стеснительный, но ты легко завоюешь его доверие с помощью вложенного лакомства — его любимого соляного камня!$B$B--Бреанни'),
(2536, 'ruRU', 'Гора верховых животных', 'Я слышала, что твои конюшни теперь почти такие же обширные, как мои. Впечатляет! Возможно, мы можем помочь друг другу... У меня слишком много дракондоров, и я надеялась, что ты найдёшь дом для одного из них. Естественно, он обучен как верховое животное, а не охотничий питомец, и ты найдёшь его таким же верным и неутомимым, как любой другой скакун, которого я вырастила. $B Снова твоя,Мэй'),
(2537, 'ruRU', 'Гора верховых животных', 'Я слышала, что твои конюшни теперь почти такие же обширные, как мои. Впечатляет! Возможно, мы можем помочь друг другу... У меня слишком много дракондоров, и я надеялась, что ты найдёшь дом для одного из них. Естественно, он обучен как верховое животное, а не охотничий питомец, и ты найдёшь его таким же верным и неутомимым, как любой другой скакун, которого я вырастила. $B Снова твоя,Мэй'),
(3478, 'ruRU', 'Индюк, которого пока не съели', 'Можешь поверить, что этот Жирный Индюк пережил весь ноябрь? $B$BВсе его друзья уже оказались на Праздничных Столах с Клюквенным Чатни и Пряным Хлебным Пудингом и... ох... у меня уже слюнки текут. Но ладно! Теперь он совсем один, и я надеялась, что ты сможешь позаботиться о нём. В моей лавке просто не осталось места! $B$BТолько, пожалуйста, держи его подальше от кухонных костров. У него появляется этот странный взгляд, когда он рядом с огнём...'),
(3857, 'ruRU', 'Мастер Острова Завоевания', 'Доблестный $N,$B$BЗа твои заслуги на Острове Завоевания для меня честь вручить тебе этот налатник. Носи его с гордостью.$B$BГлавнокомандующий, 7-й легион'),
(3957, 'ruRU', 'Мастер Острова Завоевания', 'Доблестный $N,$B$BЗа твои заслуги на Острове Завоевания для меня честь вручить тебе этот налатник. Носи его с гордостью.$B$BПовелитель Агмар'),
(4845, 'ruRU', 'Слава героя Катаклизма', NULL),
(4853, 'ruRU', 'Слава рейдера Катаклизма', NULL),
(5325, 'ruRU', 'Боевой волк Орды', 'Сколько голов Альянса легло в пыль от твоей руки? Сколько побед одержано, врагов сокрушено, полей боя взято? $B$BГлаза Адского Крика следили за тобой, и они довольны. Скачи же с гордостью, во имя Орды! $B$BВоевода Гаррош Адский Крик.'),
(5326, 'ruRU', 'Боевой волк Орды', 'Сколько голов Альянса легло в пыль от твоей руки? Сколько побед одержано, врагов сокрушено, полей боя взято? $B$BГлаза Адского Крика следили за тобой, и они довольны. Скачи же с гордостью, во имя Орды! $B$BВоевода Гаррош Адский Крик.'),
(5328, 'ruRU', 'Боевой скакун Альянса', 'Снова и снова твоё мастерство и доблесть подтверждались на поле боя. $B$BТвои деяния не останутся без награды. Скачи же с гордостью, во имя Альянса! $B$BТвой король.'),
(5329, 'ruRU', 'Боевой скакун Альянса', 'Снова и снова твоё мастерство и доблесть подтверждались на поле боя. $B$BТвои деяния не останутся без награды. Скачи же с гордостью, во имя Альянса! $B$BТвой король.'),
(5449, 'ruRU', 'Любитель камней', NULL),
(5823, 'ruRU', 'Боевой скакун Альянса', 'Снова и снова твоё мастерство и доблесть подтверждались на поле боя. $B$BТвои деяния не останутся без награды. Скачи же с гордостью, во имя Альянса! $B$BТвой король.'),
(5824, 'ruRU', 'Боевой волк Орды', 'Сколько голов Альянса легло в пыль от твоей руки? Сколько побед одержано, врагов сокрушено, полей боя взято? $B$BГлаза Адского Крика следили за тобой, и они довольны. Скачи же с гордостью, во имя Орды! $B$BВоевода Гаррош Адский Крик.'),
(5828, 'ruRU', 'Слава рейдера Огненных Просторов', NULL),
(5859, 'ruRU', 'Оставлено позади', 'Я нашёл этот медальон в Пламенных Глубинах, у самого края лавы. Он не мой, и я знаю, что он не принадлежит ни одному из Архидруидов. Возможно, он принадлежал одному из огненных друидов. $B$BКем бы ни был его владелец, мне он не нужен. Прими его как небольшой знак нашей благодарности за всё, что ты для нас сделал.'),
(5860, 'ruRU', 'Пожалуйста... просто возьми его', 'С тех пор как его брата увели. Это маленькое создание доставляет немало хлопот. Мы со стражами делаем всё возможное, чтобы сдержать его энергию, но наши усилия, к сожалению, не увенчались успехом. Теперь всё ясно. Он хочет быть со своим братом. У нас ушёл почти час, чтобы его утихомирить. Пожалуйста, возьми его с собой. Возможно, немного времени вне этой пещеры пойдёт ему на пользу.      -Фарден Коготь Сокола'),
(5866, 'ruRU', 'Подарок от архидруида', 'Больше никогда Хиджал не содрогнётся под безжалостным натиском Пламени. Никогда больше смертные расы этого мира не будут трепетать перед прислужниками Рагнароса. $B$BТеперь, благодаря твоим усилиям, трепетать будут перед Нами. $B$BТвой героизм на Огненных Просторах стал решающим в борьбе с Повелителем Огня. Ты собрал союзников со всего Калимдора и превратил их в настоящую армию. Ты сражался с прислужниками Рагнароса... и победил. За это мы выражаем тебе глубочайшую благодарность.'),
(5875, 'ruRU', 'Пожалуйста... просто возьми', 'Вот твоя награда!'),
(5876, 'ruRU', 'Пожалуйста... просто возьми его', 'Привет снова, друг!\n\nЭтот озорной малыш сводит с ума\nвсех в зоомагазине!\n\nЯ подумала, может быть, ты возьмёшь\nего с собой в некоторые из своих приключений...\nвозможно, он успокоится, повидав\nнемного мира.\n\nТы ведь носишь шлем, да...?\n\n--Бреанни'),
(5877, 'ruRU', 'Пожалуйста... просто возьми', 'Вот твоя награда!'),
(6169, 'ruRU', 'Слава рейдера «Души дракона»', NULL),
(6375, 'ruRU', 'Покоритель испытаний: серебро', NULL),
(6582, 'ruRU', 'Профи боёв питомцев', NULL),
(6716, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6754, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6827, 'ruRU', 'Посол пандаренов', 'Привет, путешественник! $B$BДавно мы не видели такого преданного нашим местным пандаренским фракциям. Ты вложил немало дней упорного труда, чтобы достичь этой высокой цели. $B$BПрими этот знак нашей признательности и знай, что тебе всегда рады в Пандарии. $B$BХранитель истории Чо.'),
(6828, 'ruRU', 'Посол пандаренов', 'Привет, путешественник! $B$BДавно мы не видели такого преданного нашим местным пандаренским фракциям. Ты вложил немало дней упорного труда, чтобы достичь этой высокой цели. $B$BПрими этот знак нашей признательности и знай, что тебе всегда рады в Пандарии. $B$BХранитель истории Чо.'),
(6846, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6847, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6850, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6855, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6856, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6857, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6858, 'ruRU', 'Возьми своё задание', 'Обратись к Чо, чтобы подтвердить это задание'),
(6927, 'ruRU', 'Слава героя Пандарии', NULL),
(6932, 'ruRU', 'Слава рейдера Пандарии', NULL),
(7385, 'ruRU', 'Почётный бочонок пивовара', 'Спасибо за весь твой тяжкий труд над лучшими сортами пива, которые мы когда-либо пробовали! $B$BВ знак нашей признательности мы с остальными пивоварами решили подарить тебе этот Почётный бочонок пивовара. $B$BНаслаждайся! $B$BМама Хмелеварка.'),
(7499, 'ruRU', 'Укрощение мира', NULL),
(7500, 'ruRU', 'Пожалуйста... просто возьми', 'Вот твоя награда!'),
(7501, 'ruRU', 'Пожалуйста... просто возьми', 'Вот твоя награда!'),
(7520, 'ruRU', 'Хранитель истории', NULL),
(7521, 'ruRU', 'Пора открывать зоомагазин', NULL),
(7860, 'ruRU', 'Нам понадобится больше сёдел', 'Я слышала, что твои конюшни теперь почти такие же обширные, как мои. Впечатляет! Возможно, мы можем помочь друг другу...$b$bЭто подарок из Пандарии.$b$bСнова твоя,$bМэй'),
(7862, 'ruRU', 'Нам понадобится больше сёдел', 'Я слышала, что твои конюшни теперь почти такие же обширные, как мои. Впечатляет! Возможно, мы можем помочь друг другу...$b$bЭто подарок из Пандарии.$b$bСнова твоя,$bМэй'),
(7908, 'ruRU', 'Аки Избранный', 'Я думал, что у тебя не было ни единого шанса победить меня. $B$BЯ слышал слухи о твоём восхождении среди мастеров-укротителей, но никогда не думал, что ты зайдёшь так далеко. Теперь ты настоящий мастер. Прими этот дар в знак уважения от меня и от всех укротителей, которых ты победил на своём пути. $B$BПоздравляю! $B$BАки Избранный.'),
(7928, 'ruRU', 'Операция: кампания Стены Щитов', NULL),
(7929, 'ruRU', 'Кампания Наступления Доминирования', NULL),
(7934, 'ruRU', 'Рейд на поводке', NULL),
(7939, 'ruRU', 'Пропуск в Бойцовский клуб', 'У тебя уже немало последователей в Брол''гаре! Мне любопытно, на что способны твои друзья. $B$BВот приглашение, которое можно вручить. Пусть здесь появится свежая кровь! $B$BБосс Баззелфланж.'),
(7940, 'ruRU', 'Пропуск в Бойцовский клуб', 'У тебя уже немало последователей в Брол''гаре! Мне любопытно, на что способны твои друзья. $B$BВот приглашение, которое можно вручить. Пусть здесь появится свежая кровь! $B$BБосс Баззелфланж.'),
(8124, 'ruRU', 'Слава рейдера Трона Грома', NULL),
(8293, 'ruRU', 'Рейд на поводке II: издание настройки', NULL),
(8300, 'ruRU', 'Свирепый укротитель питомцев', NULL),
(8335, 'ruRU', 'Пропуск в Бойцовский клуб', 'У тебя уже немало последователей в Брол''гаре! Мне любопытно, на что способны твои друзья. $B$BВот приглашение, которое можно вручить. Пусть здесь появится свежая кровь! $B$BБосс Баззелфланж.'),
(8337, 'ruRU', 'Пропуск в Бойцовский клуб', 'У тебя уже немало последователей в Брол''гаре! Мне любопытно, на что способны твои друзья. $B$BВот приглашение, которое можно вручить. Пусть здесь появится свежая кровь! $B$BБосс Баззелфланж.'),
(8340, 'ruRU', 'Обмотки кровавого бойца', 'Давай быстро подсчитаем: ты победил акулу, механического крокольва, кучу слизи, пару пингвинов и целый зал смертоносных бойцов со всего света. $B$BДа, я бы сказал, что ты заслужил рубашку.'),
(8343, 'ruRU', 'Обмотки кровавого бойца', 'Давай быстро подсчитаем: ты победил акулу, механического крокольва, кучу слизи, пару пингвинов и целый зал смертоносных бойцов со всего света. $B$BДа, я бы сказал, что ты заслужил рубашку.'),
(8345, 'ruRU', 'Очажный скакун', 'Эта прекрасная магическая конструкция прибыла только вчера, и ты первый, о ком я подумала. $B$BНаслаждайся! $B$BМэй Франсис $B$BЭкзотические транспортные средства $B$BДаларан.'),
(8348, 'ruRU', 'Самый долгий день', NULL),
(8398, 'ruRU', 'Легенда рейдов: Гаррош Адский Крик (10 игроков)', NULL),
(8399, 'ruRU', 'Легенда рейдов: Гаррош Адский Крик (25 игроков)', NULL),
(8454, 'ruRU', 'Слава рейдера Оргриммара', NULL),
(8484, 'ruRU', 'Жестокий боец', NULL),
(8485, 'ruRU', 'Жестокий боец', NULL),
